 string VerifyJourneyFeatures(){var original=save;bool prior=verifying;int h=heroIndex,pet=selectedDragon,curse=selectedCurse;verifying=true;save=new SaveData();heroIndex=0;selectedDragon=selectedCurse=-1;StartRun();if(IsHeroUnlocked(3)||!SpawnRescue())throw new Exception("Fresh profile rescue lock/spawn failed");pos=rescuePosition;if(!BeginRescue())throw new Exception("Rescue interaction failed");var guard=enemies.Find(e=>e.rescueGuard);Damage(guard,guard.maxHp+1);if(!IsHeroUnlocked(3)||rescueHero>=0)throw new Exception("Rescue kill did not unlock hero");if(!SpawnRescue())throw new Exception("Second rescue missing");pos=rescuePosition;BeginRescue();UpdateRescue(46);if(IsHeroUnlocked(4)||rescueHero>=0)throw new Exception("Failed rescue unlocks hero");foreach(int type in new[]{3,6,7,4}){StartRun();var boss=SpawnEnemy(type,false);boss.p=Vector2.right*4;Damage(boss,boss.maxHp*.51f);if(!boss.phaseTwo)throw new Exception("Boss phase threshold failed");float speed=boss.speed;TryBossPhase(boss);if(boss.speed!=speed)throw new Exception("Boss enrages twice");boss.attack=0;UpdateEnemies(.01f);if(type==3&&boss.chargeDelay<=0||type==6&&shots.Count==0||type==7&&hazards.Count<4||type==4&&shots.Count<12)throw new Exception("Boss second phase pattern missing");}
